SELECT public.fn_cp_import_case('sensible-vehicule-abandonne-proximite-rassemblement', '{"slug": "sensible-vehicule-abandonne-proximite-rassemblement", "title": "Stationne en double file depuis deux heures, moteur froid", "theme_slug": "situations-sensibles", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 18 heures. A proximite des abords d''un evenement rassemblant plusieurs milliers de personnes, un collegue en patrouille vous signale un vehicule stationne en double file depuis au moins deux heures, moteur froid, sans occupant visible ni signe d''activite recente autour de lui. Un objet volumineux, dont la nature exacte n''est pas identifiable de l''exterieur, occupe la banquette arriere. Aucune plainte pour vehicule vole ne correspond a cette plaque d''immatriculation dans les bases consultees. Le contexte evenementiel impose une vigilance particuliere, meme si l''explication la plus probable reste un stationnement genant banal.", "questions": [{"position": 1, "max_points": 5, "label": "Quelle est votre premiere action face a ce vehicule dans ce contexte evenementiel ?", "hint": "Le contexte impose la vigilance, mais rien ne justifie encore une reaction disproportionnee.", "perfect": "J''etablis un perimetre et verifie le proprietaire sans manipulation, ces deux actions restant prioritaires compte tenu du contexte evenementiel a proximite. Je maintiens une distance raisonnable autour de ce vehicule, sans pour autant declencher une alerte disproportionnee au premier constat. Je consulte les bases disponibles pour identifier le proprietaire a partir de cette plaque d''immatriculation. Je ne touche a aucun moment ce vehicule ni cet objet visible a l''interieur.", "points": [{"position": 1, "label": "Etablir un perimetre et verifier le proprietaire sans manipulation", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["perimetre etabli", "proprietaire verifie", "manipulation evitee"]}]}, {"position": 2, "label": "Maintenir une distance raisonnable sans alerte disproportionnee", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Proportionnalite de la reaction initiale.", "groups": [{"position": 1, "keywords": ["distance maintenue", "proportionnalite respectee", "alerte mesuree"]}]}, {"position": 3, "label": "Consulter les bases disponibles pour identifier le proprietaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Identification recherchee.", "groups": [{"position": 1, "keywords": ["bases consultees", "proprietaire recherche", "identification tentee"]}]}, {"position": 4, "label": "Ne toucher a aucun moment ce vehicule ni son contenu visible", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Prudence maintenue.", "groups": [{"position": 1, "keywords": ["vehicule non touche", "contenu preserve", "prudence appliquee"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment adaptez-vous votre niveau de vigilance a la proximite de ce rassemblement important ?", "hint": "Le meme vehicule stationne loin de tout evenement n''appellerait sans doute pas le meme traitement.", "perfect": "Je tiens compte de la proximite de ce rassemblement dans mon appreciation du niveau de vigilance a adopter, sans pour autant presumer une intention malveillante. J''informe les organisateurs ou responsables de securite de l''evenement de cette situation, leur vigilance pouvant se combiner utilement a la mienne. Je sollicite, si le contexte le justifie, une verification specialisee de ce vehicule plutot que de me contenter d''une simple surveillance. Je reste attentive a l''evolution de la situation, notamment si quelqu''un s''approchait de ce vehicule.", "points": [{"position": 1, "label": "Tenir compte de la proximite du rassemblement sans presumer de mauvaise intention", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Contexte integre a l''appreciation.", "groups": [{"position": 1, "keywords": ["contexte integre", "vigilance adaptee", "presomption evitee"]}]}, {"position": 2, "label": "Informer les organisateurs ou responsables de securite de l''evenement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Coordination avec les acteurs de l''evenement.", "groups": [{"position": 1, "keywords": ["organisateurs informes", "securite alertee", "coordination assuree"]}]}, {"position": 3, "label": "Solliciter une verification specialisee si le contexte le justifie", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Renfort specialise sollicite selon la gravite percue.", "groups": [{"position": 1, "keywords": ["verification specialisee", "renfort sollicite", "contexte justifiant"]}]}, {"position": 4, "label": "Rester attentive a toute personne s''approchant du vehicule", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance continue sur les abords.", "groups": [{"position": 1, "keywords": ["abords surveilles", "approche detectee", "vigilance continue"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment cloturez-vous cette verification si le proprietaire finit par se manifester avec une explication banale ?", "hint": "La vigilance initiale doit savoir ceder la place a une conclusion proportionnee une fois l''explication verifiee.", "perfect": "Je verifie l''identite de ce proprietaire et la coherence de son explication avant de lever ce perimetre, sans accepter une justification non verifiee dans un contexte aussi sensible. Je documente cette intervention factuellement, y compris l''explication finalement fournie et sa verification. Je verbalise, si necessaire, ce stationnement genant selon la procedure habituelle, independamment de cette verification de securite. Je reste courtoise avec ce proprietaire malgre la vigilance appliquee, cette situation restant, au final, banale.", "points": [{"position": 1, "label": "Verifier l''identite et la coherence de l''explication avant de lever le perimetre", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Verification avant la cloture.", "groups": [{"position": 1, "keywords": ["identite verifiee", "explication verifiee", "perimetre leve"]}]}, {"position": 2, "label": "Documenter factuellement l''explication fournie et sa verification", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Traçabilite de la resolution.", "groups": [{"position": 1, "keywords": ["intervention documentee", "explication consignee", "verification tracee"]}]}, {"position": 3, "label": "Verbaliser si necessaire le stationnement genant selon la procedure habituelle", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Suite administrative independante de la verification de securite.", "groups": [{"position": 1, "keywords": ["stationnement verbalise", "procedure habituelle", "suite administrative"]}]}, {"position": 4, "label": "Rester courtoise malgre la vigilance appliquee", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Courtoisie maintenue face a une situation finalement banale.", "groups": [{"position": 1, "keywords": ["courtoisie maintenue", "situation banale", "proprietaire respecte"]}]}]}]}'::jsonb);

