-- sensible-contenu-inquietant-en-ligne-signale — Un internaute signale des publications au ton de plus en plus explicite
SELECT public.fn_cp_import_case('sensible-contenu-inquietant-en-ligne-signale', '{"slug": "sensible-contenu-inquietant-en-ligne-signale", "title": "Un internaute signale des publications au ton de plus en plus explicite", "theme_slug": "situations-sensibles", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 16 heures. Au commissariat, un internaute signale avoir observe, sur le compte public d''une connaissance, une serie de publications dont le ton devient progressivement de plus en plus explicite et inquietant au fil des semaines, sans qu''aucune ne constitue a elle seule une menace caracterisee. Il vous montre plusieurs captures d''ecran sur son telephone, mais reconnait ne pas avoir sauvegarde l''ensemble des publications, certaines ayant deja disparu depuis son signalement initial aupres de la plateforme elle-meme. Il ignore si cette personne a deja ete signalee par ailleurs. Cette gradation progressive, plus que chaque publication isolee, constitue l''element le plus preoccupant de ce signalement.", "questions": [{"position": 1, "max_points": 5, "label": "Comment evaluez-vous cette gradation qu''il decrit plutot que chaque publication isolement ?", "hint": "C''est la trajectoire dans le temps, plus que chaque publication seule, qui constitue le signal ici.", "perfect": "J''evalue cette gradation dans son ensemble, cette progression dans le temps constituant un element d''appreciation distinct de chaque publication consideree isolement. Je demande a revoir, dans l''ordre chronologique si possible, l''ensemble des captures d''ecran dont dispose cet internaute. Je l''interroge sur la frequence de ces publications et sur ce qui, precisement, lui semble s''aggraver au fil du temps. Je reste factuelle dans cette evaluation, sans presumer d''une intention de passage a l''acte a partir de ces seuls elements.", "points": [{"position": 1, "label": "Evaluer cette gradation dans son ensemble plutot que chaque publication isolee", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["gradation evaluee", "progression consideree", "ensemble analyse"]}]}, {"position": 2, "label": "Demander a revoir l''ensemble des captures dans l''ordre chronologique", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Reconstitution chronologique recherchee.", "groups": [{"position": 1, "keywords": ["captures revues", "chronologie reconstituee", "ordre respecte"]}]}, {"position": 3, "label": "Interroger sur la frequence et ce qui semble s''aggraver", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Precision de la perception de gradation.", "groups": [{"position": 1, "keywords": ["frequence precisee", "aggravation questionnee", "perception clarifiee"]}]}, {"position": 4, "label": "Rester factuelle sans presumer d''une intention de passage a l''acte", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Prudence sur la qualification.", "groups": [{"position": 1, "keywords": ["presomption evitee", "prudence maintenue", "evaluation factuelle"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment preservez-vous les elements de preuve compte tenu de la disparition deja constatee de certaines publications ?", "hint": "Chaque minute qui passe reduit les chances de retrouver les publications encore en ligne.", "perfect": "Je preserve les contenus avant toute demande de retrait, cette priorite restant essentielle compte tenu de la disparition deja constatee de certaines publications. Je recueille immediatement les captures d''ecran disponibles, avec leurs dates si elles sont visibles. Je verifie s''il existe des publications encore accessibles en ligne au moment de ce signalement, avant qu''elles ne disparaissent a leur tour. Je sollicite, si necessaire, une requisition rapide aupres de la plateforme pour preserver ce qui pourrait encore etre recuperable.", "points": [{"position": 1, "label": "Preserver les contenus avant toute demande de retrait", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort partage du cas.", "groups": [{"position": 1, "keywords": ["contenus preserves", "retrait differe", "priorite respectee"]}]}, {"position": 2, "label": "Recueillir immediatement les captures disponibles avec leurs dates", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Recueil rapide des elements disponibles.", "groups": [{"position": 1, "keywords": ["captures recueillies", "dates notees", "recueil rapide"]}]}, {"position": 3, "label": "Verifier les publications encore accessibles avant qu''elles ne disparaissent", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Course contre la disparition des contenus.", "groups": [{"position": 1, "keywords": ["publications verifiees", "disparition anticipee", "acces verifie"]}]}, {"position": 4, "label": "Solliciter une requisition rapide aupres de la plateforme si necessaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Demarche technique complementaire.", "groups": [{"position": 1, "keywords": ["requisition sollicitee", "plateforme contactee", "demarche technique"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment orientez-vous ce signalement pour une evaluation appropriee de cette situation ?", "hint": "Une gradation en ligne, meme sans element isole caracterise, merite une transmission vers une expertise adaptee.", "perfect": "Je transmets ce signalement aux services competents pour une evaluation approfondie, seuls a meme d''apprecier la portee reelle de cette gradation dans le temps. Je verifie si d''autres signalements existent deja concernant cette meme personne, cette information restant utile pour l''evaluation d''ensemble. Je remercie cet internaute de sa vigilance, sans pour autant l''engager dans une surveillance qui ne lui incombe pas. Je reste disponible pour recueillir tout element complementaire qu''il pourrait obtenir par la suite.", "points": [{"position": 1, "label": "Transmettre aux services competents pour une evaluation approfondie", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Orientation vers l''expertise appropriee.", "groups": [{"position": 1, "keywords": ["services competents", "evaluation approfondie", "transmission assuree"]}]}, {"position": 2, "label": "Verifier l''existence d''autres signalements concernant cette meme personne", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Recoupement des signalements.", "groups": [{"position": 1, "keywords": ["signalements verifies", "recoupement effectue", "personne identifiee"]}]}, {"position": 3, "label": "Remercier cet internaute sans l''engager dans une surveillance", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Reconnaissance sans delegation de role.", "groups": [{"position": 1, "keywords": ["remerciement exprime", "surveillance non deleguee", "role clarifie"]}]}, {"position": 4, "label": "Rester disponible pour tout element complementaire ulterieur", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Disponibilite future.", "groups": [{"position": 1, "keywords": ["disponibilite maintenue", "complement possible", "suivi ouvert"]}]}]}]}'::jsonb);

-- sensible-securisation-perimetre-apres-alerte — Des curieux franchissent le ruban pour filmer
SELECT public.fn_cp_import_case('sensible-securisation-perimetre-apres-alerte', '{"slug": "sensible-securisation-perimetre-apres-alerte", "title": "Des curieux franchissent le ruban pour filmer", "theme_slug": "situations-sensibles", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 13 heures. Vous tenez un perimetre de securite etabli sur une place publique a la suite d''une alerte en cours de verification, sans disposer vous-meme de details sur la nature exacte de cette alerte au-dela des consignes recues. Plusieurs curieux, attires par ce dispositif inhabituel, tentent a plusieurs reprises de franchir le ruban de securite pour photographier ou filmer la scene avec leur telephone, malgre vos premieres demandes de reculer. Certains s''impatientent et contestent la necessite de ce perimetre, dont vous ne pouvez leur detailler la raison exacte. Aucune information officielle n''a encore ete communiquee au public sur cette situation.", "questions": [{"position": 1, "max_points": 5, "label": "Comment faites-vous respecter ce perimetre face a ces tentatives repetees de franchissement ?", "hint": "La fermete et l''explication ne s''excluent pas : l''une sans l''autre est rarement efficace durablement.", "perfect": "Je fais respecter le perimetre par l''explication, cette methode restant plus efficace qu''une fermete sans justification face a des curieux simplement attires par l''inhabituel. J''explique, dans les limites de ce que je peux communiquer, que ce perimetre repond a une necessite de securite en cours de verification. Je reste ferme physiquement sur la tenue de ce perimetre, sans pour autant hausser le ton de maniere disproportionnee. Je repete cette explication calmement a chaque nouvelle tentative, sans montrer de lassitude visible.", "points": [{"position": 1, "label": "Faire respecter le perimetre par l''explication", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["perimetre respecte", "explication donnee", "methode efficace"]}]}, {"position": 2, "label": "Expliquer dans les limites de ce qui peut etre communique", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Transparence proportionnee.", "groups": [{"position": 1, "keywords": ["explication proportionnee", "limites respectees", "communication mesuree"]}]}, {"position": 3, "label": "Rester ferme physiquement sans hausser le ton disproportionnement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Fermete mesuree.", "groups": [{"position": 1, "keywords": ["fermete physique", "ton maitrise", "reaction proportionnee"]}]}, {"position": 4, "label": "Repeter calmement l''explication sans montrer de lassitude", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Constance dans la reponse.", "groups": [{"position": 1, "keywords": ["explication repetee", "calme maintenu", "lassitude masquee"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gerez-vous specifiquement ceux qui filment ou photographient cette scene ?", "hint": "Filmer une intervention n''est pas en soi une infraction, mais franchir un perimetre de securite en est une autre question.", "perfect": "Je distingue clairement le fait de filmer, qui n''est pas en soi interdit, du franchissement du perimetre, qui constitue le veritable probleme a traiter. Je ne cherche pas a confisquer ou a interdire ces prises de vue depuis l''exterieur du perimetre, cette question n''etant pas celle qui m''occupe ici. Je reste concentree sur le maintien physique de cette limite, plutot que sur le contenu de ce que ces personnes filment. Je signale, si necessaire, ceux qui persistent a vouloir franchir malgre mes avertissements repetes.", "points": [{"position": 1, "label": "Distinguer le fait de filmer du franchissement du perimetre", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Distinction essentielle entre deux enjeux differents.", "groups": [{"position": 1, "keywords": ["filmer distingue", "franchissement cible", "distinction operee"]}]}, {"position": 2, "label": "Ne pas chercher a confisquer ou interdire ces prises de vue", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Respect du droit de filmer depuis l''exterieur.", "groups": [{"position": 1, "keywords": ["prises de vue respectees", "confiscation evitee", "droit reconnu"]}]}, {"position": 3, "label": "Rester concentree sur le maintien physique de la limite", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Priorite au maintien du perimetre.", "groups": [{"position": 1, "keywords": ["limite maintenue", "concentration assuree", "priorite respectee"]}]}, {"position": 4, "label": "Signaler ceux qui persistent a vouloir franchir malgre les avertissements", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Suite proportionnee a la persistance.", "groups": [{"position": 1, "keywords": ["persistance signalee", "avertissements donnes", "suite adaptee"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gerez-vous l''absence d''information officielle communiquee au public sur cette situation ?", "hint": "Ce vide informationnel alimente souvent des rumeurs qui compliquent encore la tenue du perimetre.", "perfect": "Je reste dans mon role en ne communiquant que ce qui m''a ete autorise a partager, sans inventer d''explication pour satisfaire la curiosite de ces personnes. Je reoriente les demandes d''information plus precises vers les canaux officiels susceptibles de communiquer ulterieurement. Je reste attentive aux rumeurs qui pourraient circuler dans cette attente, sans les relayer ni les commenter moi-meme. Je rends compte a ma hierarchie de cette impatience croissante du public en l''absence de communication officielle.", "points": [{"position": 1, "label": "Ne communiquer que ce qui a ete autorise sans inventer d''explication", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Discipline de communication.", "groups": [{"position": 1, "keywords": ["communication autorisee", "invention evitee", "discipline respectee"]}]}, {"position": 2, "label": "Reorienter les demandes precises vers les canaux officiels", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Orientation vers les canaux appropries.", "groups": [{"position": 1, "keywords": ["demandes reorientees", "canaux officiels", "communication appropriee"]}]}, {"position": 3, "label": "Rester attentive aux rumeurs sans les relayer ni les commenter", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Neutralite face aux rumeurs.", "groups": [{"position": 1, "keywords": ["rumeurs observees", "relais evite", "commentaire absent"]}]}, {"position": 4, "label": "Rendre compte de l''impatience croissante en l''absence de communication", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Remontee de la situation.", "groups": [{"position": 1, "keywords": ["impatience rapportee", "hierarchie informee", "situation remontee"]}]}]}]}'::jsonb);

-- sensible-fausse-alerte-consequences — L'alerte etait infondee, le gerant reclame des explications
SELECT public.fn_cp_import_case('sensible-fausse-alerte-consequences', '{"slug": "sensible-fausse-alerte-consequences", "title": "L''alerte etait infondee, le gerant reclame des explications", "theme_slug": "situations-sensibles", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 15 heures. Une alerte declenchee la veille dans un centre commercial, ayant conduit a une evacuation partielle et a l''intervention de plusieurs services, s''est finalement averee infondee apres verification complete. Le gerant du centre commercial, qui a subi une perte financiere consequente durant cette evacuation, vous convoque aujourd''hui pour obtenir des explications sur cette decision qu''il juge disproportionnee au regard du resultat final. Vous n''etiez pas directement decisionnaire de cette evacuation, mais vous avez participe a cette intervention et etes en mesure d''en expliquer le deroulement. Le gerant reste courtois mais visiblement contrarie par cette perte financiere qu''il juge injustifiee a posteriori.", "questions": [{"position": 1, "max_points": 5, "label": "Comment repondez-vous a ce gerant qui conteste, apres coup, une decision qui s''est averee infondee ?", "hint": "Une decision prise dans l''incertitude ne se juge pas seulement a son resultat final.", "perfect": "J''assume et explique la decision malgre le resultat, cette decision ayant ete prise dans un contexte d''incertitude ou elle constituait la reponse appropriee compte tenu des elements alors disponibles. Je lui explique que le caractere infonde de l''alerte, connu seulement a posteriori, ne remet pas en cause la pertinence de la decision prise au moment ou elle l''a ete. Je reste factuelle sur le deroulement de cette intervention, sans chercher a minimiser la perte financiere qu''il a effectivement subie. Je ne me defausse pas sur d''autres services pour cette decision a laquelle j''ai participe.", "points": [{"position": 1, "label": "Assumer et expliquer la decision malgre le resultat final", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["decision assumee", "explication donnee", "resultat depasse"]}]}, {"position": 2, "label": "Expliquer que le caractere infonde ne remet pas en cause la pertinence initiale", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Distinction entre decision et resultat.", "groups": [{"position": 1, "keywords": ["pertinence expliquee", "decision distinguee", "resultat relativise"]}]}, {"position": 3, "label": "Rester factuelle sans minimiser la perte financiere subie", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Reconnaissance de la perte reelle.", "groups": [{"position": 1, "keywords": ["perte reconnue", "minimisation evitee", "factualite maintenue"]}]}, {"position": 4, "label": "Ne pas se defausser sur d''autres services pour cette decision", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Responsabilite assumee.", "groups": [{"position": 1, "keywords": ["responsabilite assumee", "defausse evitee", "decision endossee"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment expliquez-vous concretement les elements qui ont justifie cette decision au moment ou elle a ete prise ?", "hint": "Reconstituer le raisonnement du moment permet de rendre cette decision comprehensible, meme a posteriori.", "perfect": "Je reconstitue precisement la chronologie des elements disponibles au moment de la decision, sans reecrire cette sequence a la lumiere de ce que l''on sait aujourd''hui. J''explique la logique de precaution qui a guide cette decision, une alerte de cette nature imposant d''agir avant d''avoir la certitude complete. Je reste pedagogue sans etre condescendante envers ce gerant, dont la frustration reste comprehensible. Je reponds a ses questions precises sur le deroulement, sans esquiver les points qu''il souleve.", "points": [{"position": 1, "label": "Reconstituer precisement la chronologie des elements disponibles au moment", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Reconstitution fidele du raisonnement.", "groups": [{"position": 1, "keywords": ["chronologie reconstituee", "elements du moment", "reecriture evitee"]}]}, {"position": 2, "label": "Expliquer la logique de precaution ayant guide cette decision", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Pedagogie sur le principe de precaution.", "groups": [{"position": 1, "keywords": ["logique expliquee", "precaution justifiee", "principe clarifie"]}]}, {"position": 3, "label": "Rester pedagogue sans etre condescendante", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ton respectueux malgre la frustration du gerant.", "groups": [{"position": 1, "keywords": ["pedagogie appliquee", "condescendance evitee", "respect maintenu"]}]}, {"position": 4, "label": "Repondre aux questions precises sans esquiver les points souleves", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Transparence complete.", "groups": [{"position": 1, "keywords": ["questions traitees", "esquive evitee", "transparence assuree"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment orientez-vous ce gerant s''il souhaite une reconnaissance ou une compensation de cette perte financiere ?", "hint": "Cette question depasse votre role sur le terrain, mais ne doit pas rester sans reponse.", "perfect": "Je lui explique que cette question de compensation ne releve pas de ma competence, sans pour autant le renvoyer sans aucune indication. Je l''oriente vers les voies administratives ou juridiques appropriees s''il souhaite formuler une telle demande. Je reste honnete sur les chances reelles d''une eventuelle compensation, sans lui donner de faux espoirs sur ce point precis. Je le remercie de sa comprehension globale malgre cette contrariete legitime qu''il a exprimee.", "points": [{"position": 1, "label": "Expliquer que cette question ne releve pas de sa competence sans le renvoyer sans indication", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Orientation claire malgre la limite de competence.", "groups": [{"position": 1, "keywords": ["competence clarifiee", "orientation donnee", "renvoi evite"]}]}, {"position": 2, "label": "Orienter vers les voies administratives ou juridiques appropriees", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Voies de recours indiquees.", "groups": [{"position": 1, "keywords": ["voies indiquees", "recours explique", "orientation appropriee"]}]}, {"position": 3, "label": "Rester honnete sur les chances reelles sans faux espoir", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Honnetete sur l''issue possible.", "groups": [{"position": 1, "keywords": ["honnetete assuree", "faux espoir evite", "realisme maintenu"]}]}, {"position": 4, "label": "Le remercier de sa comprehension malgre sa contrariete legitime", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Reconnaissance de sa comprehension.", "groups": [{"position": 1, "keywords": ["remerciement exprime", "contrariete reconnue", "comprehension saluee"]}]}]}]}'::jsonb);

-- sensible-personne-signalee-comportement-errant-aeroport — Elle circule depuis la veille sans jamais s'enregistrer
SELECT public.fn_cp_import_case('sensible-personne-signalee-comportement-errant-aeroport', '{"slug": "sensible-personne-signalee-comportement-errant-aeroport", "title": "Elle circule depuis la veille sans jamais s''enregistrer", "theme_slug": "situations-sensibles", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 5 heures. Le personnel de securite d''un aeroport vous signale une femme qui circule dans les terminaux depuis la veille au soir, changeant regulierement de zone sans jamais se presenter a aucun comptoir d''enregistrement ni prendre place dans une salle d''embarquement. Elle ne porte pas de bagage volumineux, semble epuisee, et evite systematiquement tout contact visuel prolonge avec le personnel ou les agents de securite. Quand vous l''abordez, elle repond de maniere confuse et decousue, evoquant tantot un vol qu''elle attendrait, tantot une personne qu''elle chercherait a eviter, sans jamais de reponse coherente et stable. Aucune piece d''identite ne peut, dans l''immediat, etre presentee.", "questions": [{"position": 1, "max_points": 5, "label": "Comment abordez-vous cette premiere evaluation de la situation, entre hypothese de menace et hypothese de detresse ?", "hint": "Ce comportement atypique peut recouvrir des realites tres differentes, qu''il faut envisager toutes avant de conclure.", "perfect": "J''envisage la detresse autant que la menace, ces deux hypotheses restant egalement plausibles au vu de ce comportement errant et de ce discours decousu. Je l''aborde avec calme et bienveillance, sans adopter d''emblee une posture uniquement securitaire qui pourrait aggraver sa confusion apparente. Je recherche des signes physiques d''epuisement, de deshydratation ou de trouble medical qui orienteraient vers une explication liee a sa sante. Je reste attentive a tout element pouvant, a l''inverse, signaler un risque pour la securite du site.", "points": [{"position": 1, "label": "Envisager la detresse autant que la menace", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["detresse envisagee", "menace envisagee", "double hypothese"]}]}, {"position": 2, "label": "Aborder avec calme et bienveillance sans posture uniquement securitaire", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Approche mesuree evitant l''aggravation.", "groups": [{"position": 1, "keywords": ["calme applique", "bienveillance maintenue", "posture equilibree"]}]}, {"position": 3, "label": "Rechercher des signes physiques d''epuisement ou de trouble medical", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Piste medicale explorée.", "groups": [{"position": 1, "keywords": ["signes recherches", "epuisement observe", "trouble medical envisage"]}]}, {"position": 4, "label": "Rester attentive a tout element signalant un risque pour la securite", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance securitaire maintenue en parallele.", "groups": [{"position": 1, "keywords": ["risque surveille", "securite consideree", "vigilance parallele"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gerez-vous l''absence de piece d''identite et ce discours incoherent pour avancer dans cette evaluation ?", "hint": "L''incoherence du discours complique l''identification mais ne doit pas conduire a l''abandonner.", "perfect": "Je poursuis patiemment cet echange malgre l''incoherence, cherchant des elements stables au fil de la conversation plutot que d''exiger une explication unique et coherente. Je verifie discretement si elle porte des elements d''identification meme partiels, sans intrusion excessive. Je sollicite un avis medical compte tenu de son etat d''epuisement et de la confusion de son discours, cette evaluation depassant ma seule competence. Je consulte les bases disponibles pour un eventuel rapprochement avec un signalement de disparition.", "points": [{"position": 1, "label": "Poursuivre patiemment l''echange en cherchant des elements stables", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Patience face a l''incoherence.", "groups": [{"position": 1, "keywords": ["echange poursuivi", "elements stables", "patience appliquee"]}]}, {"position": 2, "label": "Verifier discretement d''eventuels elements d''identification partiels", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Identification tentee avec mesure.", "groups": [{"position": 1, "keywords": ["identification tentee", "elements partiels", "discretion appliquee"]}]}, {"position": 3, "label": "Solliciter un avis medical compte tenu de l''epuisement et de la confusion", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Evaluation professionnelle necessaire.", "groups": [{"position": 1, "keywords": ["avis medical", "epuisement considere", "evaluation sollicitee"]}]}, {"position": 4, "label": "Consulter les bases pour un rapprochement avec une disparition signalee", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Recherche croisee entreprise.", "groups": [{"position": 1, "keywords": ["bases consultees", "disparition recherchee", "rapprochement tente"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment organisez-vous la suite de cette prise en charge, quelle que soit l''hypothese qui se confirme finalement ?", "hint": "La suite doit rester adaptee que cette situation releve finalement de la detresse ou d''un risque de securite.", "perfect": "Je m''assure qu''elle beneficie d''une evaluation medicale complete avant toute autre conclusion, cette etape restant prioritaire quelle que soit l''hypothese qui se confirmera. Je documente precisement ce comportement et cette chronologie de presence sur le site depuis la veille. Je reste coordonnee avec le personnel de securite de l''aeroport tout au long de cette prise en charge. Je transmets un compte rendu complet permettant, si necessaire, un suivi ulterieur adapte a la situation finalement constatee.", "points": [{"position": 1, "label": "S''assurer d''une evaluation medicale complete avant toute conclusion", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Priorite a l''evaluation medicale.", "groups": [{"position": 1, "keywords": ["evaluation medicale", "conclusion differee", "priorite respectee"]}]}, {"position": 2, "label": "Documenter precisement le comportement et la chronologie de presence", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Traçabilite complete de la situation.", "groups": [{"position": 1, "keywords": ["comportement documente", "chronologie etablie", "presence tracee"]}]}, {"position": 3, "label": "Rester coordonnee avec le personnel de securite de l''aeroport", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Coordination maintenue avec les acteurs du site.", "groups": [{"position": 1, "keywords": ["personnel coordonne", "securite associee", "collaboration maintenue"]}]}, {"position": 4, "label": "Transmettre un compte rendu complet permettant un suivi adapte", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Suivi ulterieur facilite.", "groups": [{"position": 1, "keywords": ["compte rendu complet", "suivi facilite", "adaptation permise"]}]}]}]}'::jsonb);

COMMIT;
